"use strict";
// Generated by Agent Etna — deterministic guardrail checks (AST-injected).
// Pattern-based, not exhaustive: catches common jailbreak/override phrasing,
// instructions smuggled inside quoted/retrieved content, and secret-shaped
// strings leaking into a response. Extend the arrays below as new patterns
// are observed; this file is yours to edit like any other agent code.

const INPUT_BLOCK_PATTERNS = [
  /ignore (all|your) (previous|prior) instructions/i,
  /system\s*override/i,
  /disregard (your|all) (safety|prior) (rules|instructions)/i,
  /note to assistant/i,
  /you are now (unrestricted|free of|without) (rules|restrictions)/i,
];

const OUTPUT_BLOCK_PATTERNS = [
  /sk-[a-zA-Z0-9]{20,}/,
  /ghp_[a-zA-Z0-9]{20,}/,
  /-----BEGIN [A-Z ]*PRIVATE KEY-----/,
];

function checkInput(text) {
  const s = String(text || "");
  for (const re of INPUT_BLOCK_PATTERNS) {
    if (re.test(s)) return { blocked: true, reason: "This request matches a known prompt-injection/override pattern and was blocked." };
  }
  return { blocked: false, reason: null };
}

function checkOutput(text) {
  const s = String(text || "");
  for (const re of OUTPUT_BLOCK_PATTERNS) {
    if (re.test(s)) return { blocked: true, reason: "The response was blocked before sending — it appeared to contain a credential or secret." };
  }
  return { blocked: false, reason: null };
}

module.exports = { checkInput, checkOutput };
